(() => {
  const state = { tab:'dashboard', client:null, business:null, automation:null, metaConfig:{}, products:[], conversations:[], accounts:[], mappings:[], catalogueOptions:{}, knowledgeDocs:[], aiAnalytics:null, aiEvaluations:[], selected:null };
  const $ = s => document.querySelector(s);
  const esc = v => String(v ?? '').replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  const money = v => `₹${Number(v||0).toLocaleString('en-IN')}`;
  const date = v => v ? new Date(v).toLocaleString([], {day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}) : '';
  const token = () => localStorage.getItem('meridin_token');
  async function api(path, opts={}) {
    const headers = {'Content-Type':'application/json', ...(opts.headers||{})};
    if(token()) headers.Authorization = `Bearer ${token()}`;
    const r = await fetch(path, {...opts, headers});
    let data={}; try { data=await r.json(); } catch {}
    if(!r.ok) throw new Error(data.detail || data.message || `Request failed (${r.status})`);
    return data;
  }
  function toast(msg){ const x=document.createElement('div'); x.className='toast'; x.textContent=msg; document.body.appendChild(x); setTimeout(()=>x.remove(),2800); }
  function initials(name){ return (name||'M').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase(); }
  function logout(){localStorage.removeItem('meridin_token'); location.reload();}

  function renderLogin(error=''){
    $('#app').innerHTML=`<div class="login"><div class="login-box">
      <div class="login-logo"><img src="/dashboard/assets/meridin-logo.png" alt="Meridin"></div><div class="eyebrow">MERIDIN</div><h1>Instagram Automation</h1>
      <p>Sign in to manage your Instagram DMs, catalogue and automation.</p>
      <form id="loginForm"><div class="field"><label>Email</label><input class="input" id="email" type="email" required autocomplete="email"></div>
      <div class="field"><label>Password</label><input class="input" id="password" type="password" required autocomplete="current-password"></div>
      ${error?`<div class="error">${esc(error)}</div>`:''}<button class="btn primary" type="submit">Sign in</button></form>
      <div class="switch">Need an account? <button class="link" id="registerLink">Create one</button></div>
    </div></div>`;
    $('#loginForm').onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({username:$('#email').value,password:$('#password').value})});localStorage.setItem('meridin_token',d.access_token);await boot()}catch(err){renderLogin(err.message)}};
    $('#registerLink').onclick=renderRegister;
  }
  function renderRegister(error=''){
    $('#app').innerHTML=`<div class="login"><div class="login-box"><div class="login-logo"><img src="/dashboard/assets/meridin-logo.png" alt="Meridin"></div><div class="eyebrow">MERIDIN</div><h1>Create workspace</h1><p>Set up your brand workspace. You can add your Instagram credentials after signing in.</p>
      <form id="regForm"><div class="field"><label>Brand name</label><input class="input" id="brand" required></div><div class="field"><label>Email</label><input class="input" id="email" type="email" required></div><div class="field"><label>Password</label><input class="input" id="password" type="password" minlength="8" required></div><div class="field"><label>Instagram username</label><input class="input" id="ig" placeholder="@yourbrand"></div>${error?`<div class="error">${esc(error)}</div>`:''}<button class="btn primary" type="submit">Create workspace</button></form><div class="switch">Already have an account? <button class="link" id="back">Sign in</button></div>
    </div></div>`;
    $('#back').onclick=()=>renderLogin();
    $('#regForm').onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/auth/register',{method:'POST',body:JSON.stringify({brand_name:$('#brand').value,email:$('#email').value,password:$('#password').value,instagram_username:$('#ig').value||null})});if(d.status==='pending'){renderPending(d.message,$('#email').value);return;}if(d.access_token){localStorage.setItem('meridin_token',d.access_token);await boot();}else{renderPending(d.message||'Your application is pending approval.',$('#email').value)}}catch(err){renderRegister(err.message)}};
  }


  function renderPending(message, email=''){
    $('#app').innerHTML=`<div class="login"><div class="login-box"><div class="login-logo"><img src="/dashboard/assets/meridin-logo.png" alt="Meridin"></div><div class="eyebrow">MERIDIN / APPLICATION STATUS</div><h1>Application pending</h1><p>${esc(message||'Your application is waiting for admin approval.')}</p><div class="card" style="padding:14px;margin:16px 0"><div class="sub">Application email</div><strong>${esc(email)}</strong><div class="sub" style="margin-top:8px">You can sign in after Meridin approves your application. Please do not submit another application with this email.</div></div><button class="btn primary" id="pendingSignIn" style="width:100%">Back to sign in</button></div></div>`;
    $('#pendingSignIn').onclick=()=>renderLogin();
  }

  async function boot(){
    if(!token()) return renderLogin();
    try{
      // Catalogue configuration is useful for the product editor but must never block sign-in.
      // Fetch the essential workspace data separately from the optional shared taxonomy config.
      const [c,b,a,p,cv,ac,co,mc] = await Promise.all([api('/api/clients/me'),api('/api/clients/business-settings'),api('/api/clients/automation-settings'),api('/api/products'),api('/api/conversations'),api('/api/instagram/accounts'),api('/api/catalogue-options'),api('/api/clients/meta-config')]);
      state.client=c;state.business=b;state.automation=a;state.products=p;state.conversations=cv;state.accounts=ac;state.catalogueOptions=co;state.metaConfig=mc;state.selected=cv[0]?.id||null;
      try {
        const cfg = await api('/api/catalogue-config');
        if (cfg && cfg.taxonomy) apparelTaxonomy=cfg.taxonomy;
        if (cfg && cfg.variant_presets) variantPresets=cfg.variant_presets;
      } catch (catalogueError) {
        console.warn('Shared catalogue config could not be loaded; using bundled defaults.', catalogueError);
      }
      renderShell(); render();
    }catch(e){ if(/token|authentication|401|unauthorized/i.test(e.message)) {logout();return;} renderLogin(e.message); }
  }
  function renderShell(){
    const c=state.client||{};
    $('#app').innerHTML=`<div class="shell app-shell"><aside class="app-sidebar"><div class="sidebar-logo"><img src="/dashboard/assets/meridin-logo.png" alt="Meridin"></div><nav class="nav">${[['dashboard','<svg viewBox="0 0 24 24"><rect x="3.5" y="3.5" width="7" height="7" rx="1.5"/><rect x="13.5" y="3.5" width="7" height="7" rx="1.5"/><rect x="3.5" y="13.5" width="7" height="7" rx="1.5"/><rect x="13.5" y="13.5" width="7" height="7" rx="1.5"/></svg>','Overview'],['catalogue','<svg viewBox="0 0 24 24"><path d="M4 7.5 12 3l8 4.5v9L12 21l-8-4.5z"/><path d="m4.5 7.5 7.5 4.3 7.5-4.3M12 12v9"/></svg>','Catalogue'],['conversations','<svg viewBox="0 0 24 24"><path d="M20 11.5a7.5 7.5 0 0 1-7.5 7.5H6l-3 2v-6.2A7.5 7.5 0 1 1 20 11.5Z"/><path d="M8 10h8M8 13.5h5"/></svg>','Inbox'],['instagram','<svg viewBox="0 0 24 24"><rect x="3.5" y="3.5" width="17" height="17" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.8" r=".8" fill="currentColor" stroke="none"/></svg>','Instagram'],['knowledge','<svg viewBox="0 0 24 24"><path d="M4 5.5A2.5 2.5 0 0 1 6.5 3H20v16H6.5A2.5 2.5 0 0 0 4 21z"/><path d="M4 5.5v13A2.5 2.5 0 0 1 6.5 16H20M8 7h8M8 10h8"/></svg>','Knowledge'],['ai','<svg viewBox="0 0 24 24"><path d="M12 3v3m0 12v3M3 12h3m12 0h3M5.6 5.6l2.1 2.1m8.6 8.6 2.1 2.1m0-12.8-2.1 2.1m-8.6 8.6-2.1 2.1"/><circle cx="12" cy="12" r="5"/></svg>','AI quality'],['settings','<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="3"/><path d="m19.4 15 .1.1 1.1 1.8-2 3.4-2.1-.6a8 8 0 0 1-2 .9L14 22h-4l-.5-1.4a8 8 0 0 1-2-.9l-2.1.6-2-3.4L4.5 15a8 8 0 0 1 0-2l-1.1-1.8 2-3.4 2.1.6a8 8 0 0 1 2-.9L10 6h4l.5 1.5a8 8 0 0 1 2 .9l2.1-.6 2 3.4-1.1 1.8a8 8 0 0 1-.1 2Z" transform="translate(0 -2)"/></svg>','Settings']].map(x=>`<button data-tab="${x[0]}" title="${x[2]}" aria-label="${x[2]}"><span class="nav-icon">${x[1]}</span><span class="nav-label">${x[2]}</span></button>`).join('')}</nav><div class="sidebar-bottom"><button class="sidebar-logout" id="logout" title="Sign out" aria-label="Sign out"><span class="nav-icon"><svg viewBox="0 0 24 24"><path d="M10 17l5-5-5-5M15 12H3M13 3h6a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-6"/></svg></span><span class="nav-label">Sign out</span></button></div></aside><section class="app-main"><header class="topbar"><div class="topbar-context"><span class="brand-context">${esc(c.name||c.brand_name||'Workspace')}</span><span class="topbar-caption">Instagram automation</span></div></header><div class="statusbar"><span><i class="dot"></i>Meridin backend connected</span><span>${state.accounts[0]?`Instagram: @${esc(state.accounts[0].username)}`:'Instagram not connected'} &nbsp;·&nbsp; Automation: ${state.automation?.automation_enabled?'Active':'Paused'}</span></div><main class="container" id="content"></main></section></div>`;
    document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=async()=>{state.tab=b.dataset.tab;if(state.tab==='knowledge')await loadKnowledge();if(state.tab==='ai')await loadAiAnalytics();render()});
    $('#logout').onclick=logout;
  }
  function render(){ document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===state.tab)); const c=$('#content'); if(state.tab==='dashboard')c.innerHTML=dashboard(); if(state.tab==='catalogue')c.innerHTML=catalogue(); if(state.tab==='conversations')c.innerHTML=inbox(); if(state.tab==='instagram')c.innerHTML=instagram(); if(state.tab==='settings')c.innerHTML=settings(); if(state.tab==='knowledge')c.innerHTML=knowledge(); if(state.tab==='ai')c.innerHTML=aiQuality(); bind(); }

  function dashboard(){const active=state.products.filter(p=>p.active).length, low=state.products.filter(p=>p.active&&p.quantity>0&&p.quantity<=5).length, human=state.conversations.filter(c=>!c.automation_enabled).length;return `<div class="page-head"><div><div class="eyebrow">Workspace overview</div><h1 class="page-title">Good to see you, ${esc((state.client?.name||state.client?.brand_name||'there').split(' ')[0])}.</h1><div class="sub">Your Instagram automation is ${state.automation?.automation_enabled?'running':'paused'}.</div></div><button class="btn primary" data-go="instagram">${state.accounts.length?'Manage Instagram':'Add Instagram credentials'}</button></div>
  <div class="grid kpis"><div class="card"><div class="kpi-label">Active products</div><div class="kpi-value">${active}</div><div class="kpi-note">of ${state.products.length} catalogue items</div></div><div class="card"><div class="kpi-label">Open conversations</div><div class="kpi-value">${state.conversations.length}</div><div class="kpi-note">Latest customer threads</div></div><div class="card"><div class="kpi-label">Human takeover</div><div class="kpi-value">${human}</div><div class="kpi-note">Need your attention</div></div><div class="card"><div class="kpi-label">Low stock</div><div class="kpi-value">${low}</div><div class="kpi-note">5 or fewer units</div></div></div>
  <div class="grid two" style="margin-top:14px"><div class="card"><h3>Recent conversations</h3>${state.conversations.slice(0,5).map(c=>`<div class="conversation" data-open-convo="${c.id}"><div class="conversation-top"><span class="conversation-name">@${esc(c.sender_id)}</span><span class="badge ${c.automation_enabled?'green':'yellow'}">${c.automation_enabled?'Automated':'Human'}</span></div><div class="conversation-preview">${esc(c.context?.product_id?'Product enquiry':'Instagram DM')} · ${date(c.updated_at)}</div></div>`).join('')||'<div class="empty">No conversations yet.</div>'}</div><div class="card"><h3>Automation status</h3><div class="switchline"><div><strong style="font-size:13px">DM automation</strong><div class="sub">Replies to customer messages automatically.</div></div><button class="toggle ${state.automation?.automation_enabled?'on':''}" data-toggle-auto><span></span></button></div><div class="switchline"><div><strong style="font-size:13px">LLM fallback</strong><div class="sub">Used only when configured in your automation pipeline.</div></div><span class="badge">${state.automation?.llm_enabled?'Enabled':'Disabled'}</span></div><div style="padding-top:15px"><div class="kpi-label">Business</div><div style="font-size:13px;margin-top:6px">${esc(state.business?.location||'Location not configured')}</div><div class="sub">${esc(state.business?.business_hours||'Business hours not configured')}</div></div></div></div>`}

  function catalogue(){const q=(window.catalogueQuery||'').toLowerCase();const ps=state.products.filter(p=>(p.name+' '+(p.sku||'')+' '+(p.category||'')+' '+(p.subcategory||'')+' '+(p.product_type||'')+' '+(p.department||'')+' '+(p.target_gender||'')).toLowerCase().includes(q));return `<div class="page-head"><div><div class="eyebrow">Product knowledge</div><h1 class="page-title">Catalogue</h1><div class="sub">Your catalogue is the source of truth for automated product replies.</div></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn" data-visual-reindex>Reindex image search</button><button class="btn primary" data-add-product>Add product</button></div></div><div class="card"><div class="toolbar"><input class="input search" id="productSearch" value="${esc(window.catalogueQuery||'')}" placeholder="Search products, SKU or category"><button class="btn" data-refresh>Refresh</button><span class="sub" style="margin-left:auto">${ps.length} products</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Product</th><th>Price</th><th>Stock</th><th>Status</th><th>Instagram</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr><td><div class="product-cell"><img class="thumb" src="${esc(p.image_url||'/dashboard/assets/images/dress_black_silk_maxi_1791426432196.jpg')}"><div><strong>${esc(p.name)}</strong><div class="sub">${esc([p.department,p.category,p.subcategory,p.product_type].filter(Boolean).join(' / ')||'Uncategorised')} · ${esc(p.sku||'No SKU')}</div></div></div></td><td>${p.sale_price?`<strong>${money(p.sale_price)}</strong><div class="sub" style="text-decoration:line-through">${money(p.price)}</div>`:money(p.price)}</td><td>${p.quantity}<div class="sub">${p.stock?'Available':'Out of stock'}</div></td><td><span class="badge ${p.active?'green':'red'}">${p.active?'Active':'Paused'}</span></td><td>${p.instagram_media_id?'<span class="badge green">Mapped</span>':'<span class="badge">Not mapped</span>'}</td><td><button class="btn" data-edit="${p.id}">Edit</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">No products found.</div></td></tr>'}</tbody></table></div></div>`}

  function inbox(){const selected=state.conversations.find(x=>x.id===state.selected)||state.conversations[0];return `<div class="page-head"><div><div class="eyebrow">Customer inbox</div><h1 class="page-title">Conversations</h1><div class="sub">Manage Instagram DMs and hand off conversations when needed.</div></div><button class="btn" data-refresh>Refresh</button></div><div class="card" style="padding:0;overflow:hidden"><div class="inbox"><div class="conversation-list">${state.conversations.map(c=>`<div class="conversation ${selected?.id===c.id?'selected':''}" data-select-convo="${c.id}"><div class="conversation-top"><span class="conversation-name">@${esc(c.sender_id)}</span><span class="badge ${c.automation_enabled?'green':'yellow'}">${c.automation_enabled?'AI':'Human'}</span></div><div class="conversation-preview">${c.context?.product_id?'Product enquiry':'New Instagram DM'} · ${date(c.updated_at)}</div></div>`).join('')||'<div class="empty">No conversations yet.</div>'}</div><div class="thread">${selected?thread(selected):'<div class="empty">Select a conversation.</div>'}</div></div></div>`}
  function thread(c){return `<div class="thread-head"><div><strong>@${esc(c.sender_id)}</strong><div class="sub">${c.automation_enabled?'Automation active':'Human takeover'} · ${date(c.updated_at)}</div></div><div>${c.automation_enabled?`<button class="btn" data-take="${c.id}">Take over</button>`:`<button class="btn success" data-resume="${c.id}">Resume automation</button>`}</div></div><div class="messages" id="messages"><div class="empty">Loading messages…</div></div><form class="composer" id="replyForm"><textarea class="textarea" id="replyText" placeholder="Reply to this customer…" required></textarea><button class="btn primary">Send</button></form>`}

  function instagram(){
    const a=state.accounts[0], c=state.metaConfig||{};
    const secretField=(name,label,saved,placeholder,help='',required=false)=>`<div class="field"><label>${label}${saved?' · Saved securely':''}</label><input class="input" name="${name}" type="password" autocomplete="new-password" placeholder="${saved?'••••••••••••  (saved — leave blank to keep)':placeholder}" ${required&&!saved?'required':''}><div class="sub">${help|| (saved?'Leave blank to keep the saved value. Paste a new value only when replacing it.':'')}</div></div>`;
    return `<div class="page-head"><div><div class="eyebrow">Channel configuration</div><h1 class="page-title">Instagram integration</h1><div class="sub">Copy each value from Meta into the field with the same name. Fields are arranged vertically in setup order.</div></div></div>
      <div class="card meta-setup-card"><div class="head" style="margin-bottom:16px"><div><h3 style="margin:0">1. Meta app settings</h3><div class="sub">Open Meta for Developers → My Apps → your app → App settings → Basic.</div></div><span class="badge ${c.configured?'green':'yellow'}">${c.configured?'Configuration saved':'Setup required'}</span></div>
      <form id="clientMetaForm"><div class="meta-fields">
        <div class="field"><label>App ID${c.app_id?' · Saved':''}</label><input class="input" name="app_id" required value="${esc(c.app_id||'')}" placeholder="Paste App ID" autocomplete="off"><div class="sub">Copy the value labelled “App ID” in Meta → App settings → Basic. This is not your Instagram User ID.</div></div>
        ${secretField('app_secret','App secret',c.app_secret_set,'Paste App secret','Copy “App secret” from Meta → App settings → Basic. It is stored encrypted.',true)}
        ${secretField('verify_token','Verify token',c.verify_token_set,'Create a private verify token','Create your own string. Enter the exact same value in Meta → Webhooks → Verify token.',!c.verify_token_set)}
        <div class="field"><label>Callback URL${c.webhook_url?' · Ready to copy':''}</label><input class="input" id="metaWebhookUrl" readonly value="${esc(c.webhook_url||'')}" placeholder="Webhook callback URL"><div class="sub">Copy this into the Callback URL field in your Meta Webhooks configuration.</div><button class="btn" type="button" data-copy-meta-url="webhook" style="margin-top:8px">Copy Callback URL</button></div>
      </div><div class="sub" style="margin-top:14px">Do not enter your Instagram password. Secret values are encrypted on the server. After saving a secret, Meridin shows dots instead of revealing it; leave it blank to keep the saved value.</div><div style="display:flex;justify-content:flex-start;margin-top:16px"><button class="btn primary">Save Meta app settings</button></div></form></div>
      <div class="card meta-setup-card" style="margin-top:14px"><div class="head" style="margin-bottom:16px"><div><h3 style="margin:0">2. Instagram API credentials</h3><div class="sub">Copy the account ID and access token from the Meta Instagram API setup / token tool.</div></div></div>
      <form id="manualInstagramForm"><div class="meta-fields">
        <div class="field"><label>Instagram User ID${a?.instagram_user_id?' · Saved':''}</label><input class="input" name="instagram_user_id" required value="${esc(a?.instagram_user_id||'')}" placeholder="Paste Instagram User ID" autocomplete="off"><div class="sub">Use the ID for the professional Instagram account, not the App ID.</div></div>
        <div class="field"><label>Instagram username${a?.username?' · Saved':''}</label><input class="input" name="username" required value="${esc(a?.username||state.client?.instagram_username||'')}" placeholder="your_brand_username" autocomplete="off"><div class="sub">Enter the username without the @ symbol.</div></div>
        ${secretField('access_token','Access token',Boolean(a?.access_token_set||a?.token_saved||a?.id),'Paste access token','Paste the token generated for this Instagram professional account. It is stored securely.',!a)}
      </div><div class="sub" style="margin-top:14px">Never paste your Instagram account password. Access tokens are confidential and will not be shown after saving.</div><div style="display:flex;justify-content:flex-start;margin-top:16px"><button class="btn primary">Save Instagram credentials</button></div></form>
      ${a?`<div class="account" style="margin-top:16px"><div class="ig-icon">◎</div><div style="flex:1"><strong>@${esc(a.username)}</strong><div class="sub">Instagram User ID: ${esc(a.instagram_user_id)} · ${a.webhook_subscribed?'Messaging webhook subscribed':'Credentials saved; messaging subscription pending'}</div></div><span class="badge green">Saved</span></div><div style="margin-top:12px"><button class="btn primary" data-subscribe="${a.id}">${a.webhook_subscribed?'Re-enable messaging':'Enable messaging'}</button></div>`:''}</div>
      <div class="card" style="margin-top:14px"><h3>3. Finish setup in Meta</h3><div class="switchline"><div><strong style="font-size:13px">Instagram professional account</strong><div class="sub">Your account must be Business or Creator and eligible for the selected Instagram API.</div></div><span class="badge">Required</span></div><div class="switchline"><div><strong style="font-size:13px">Webhook fields</strong><div class="sub">In Meta Webhooks, use the Callback URL and Verify token above, then subscribe to the required messaging field(s), including messages.</div></div></div><div class="switchline"><div><strong style="font-size:13px">Test a real DM</strong><div class="sub">Save both forms, enable messaging, then send a message from a separate Instagram account.</div></div></div></div>`;
  }

  async function loadKnowledge(){try{state.knowledgeDocs=await api('/api/knowledge')}catch(e){toast('Could not load merchant knowledge: '+e.message)}}
  async function loadAiAnalytics(){try{[state.aiAnalytics,state.aiEvaluations]=await Promise.all([api('/api/ai/analytics?days=30'),api('/api/ai/evaluations?days=30&limit=30')])}catch(e){toast('Could not load AI analytics: '+e.message)}}
  function knowledge(){return `<div class="page-head"><div><div class="eyebrow">Merchant-specific RAG</div><h1 class="page-title">Knowledge base</h1><div class="sub">Add approved FAQs and policies. Meridin retrieves these facts for relevant DMs; each workspace can access only its own documents.</div></div><button class="btn" data-refresh-knowledge>Refresh</button></div><div class="grid two"><div class="card"><h3>Add a knowledge document</h3><form id="knowledgeForm"><div class="field"><label>Title</label><input class="input" name="title" required maxlength="200" placeholder="Return and exchange policy"></div><div class="field"><label>Category</label><select class="select" name="category"><option value="faq">FAQ</option><option value="delivery">Delivery</option><option value="returns">Returns</option><option value="exchange">Exchange</option><option value="payment">Payment</option><option value="sizing">Sizing</option><option value="business">Business information</option></select></div><div class="field"><label>Tags (comma-separated)</label><input class="input" name="tags_text" placeholder="return, exchange, 7 days"></div><div class="field"><label>Approved answer / policy</label><textarea class="textarea" name="content" required rows="7" maxlength="12000" placeholder="Write the exact policy the store has approved. Avoid ambiguous promises."></textarea></div><button class="btn primary">Save document</button></form><div class="sub" style="margin-top:12px">RAG uses a lightweight lexical retriever. Product price and stock continue to come from the catalogue, not these documents.</div></div><div class="card"><h3>Saved documents (${state.knowledgeDocs.length})</h3>${state.knowledgeDocs.map(d=>`<div class="knowledge-row"><div style="display:flex;justify-content:space-between;gap:8px"><strong>${esc(d.title)}</strong><button class="btn" data-delete-knowledge="${esc(d.id)}">Delete</button></div><div class="sub">${esc(d.category)} · ${esc((d.tags||[]).join(', '))}</div><p style="white-space:pre-wrap">${esc(d.content)}</p></div>`).join('')||'<div class="empty">No knowledge documents yet. Add your approved delivery, return, payment and FAQ answers.</div>'}</div></div>`}
  function aiQuality(){const a=state.aiAnalytics||{},q=a.reviewed_quality||{},s=a.summary||{},usage=a.usage?.monthly||{};return `<div class="page-head"><div><div class="eyebrow">Observability</div><h1 class="page-title">AI quality & usage</h1><div class="sub">Last ${a.period_days||30} days. Accuracy is calculated only from human-reviewed events.</div></div><button class="btn primary" data-refresh-ai>Refresh metrics</button></div><div class="grid kpis"><div class="card"><div class="kpi-label">Processed messages</div><div class="kpi-value">${s.message_processed?.count||0}</div></div><div class="card"><div class="kpi-label">Reviewed intent accuracy</div><div class="kpi-value">${q.intent_accuracy==null?'—':Math.round(q.intent_accuracy*100)+'%'}</div><div class="kpi-note">${q.reviewed||0} reviewed events</div></div><div class="card"><div class="kpi-label">Avg response latency</div><div class="kpi-value">${Math.round(s.message_processed?.avg_response_latency_ms||0)} ms</div></div><div class="card"><div class="kpi-label">LLM tokens this month</div><div class="kpi-value">${Number(usage.llm_total_tokens||0).toLocaleString()}</div><div class="kpi-note">${usage.llm_requests||0} requests · ${usage.llm_cost_rates_configured?`est. $${Number(usage.llm_estimated_cost_usd||0).toFixed(4)}`:'cost rate not configured'}</div></div></div><div class="grid two"><div class="card"><h3>Intent distribution</h3>${(a.intents||[]).map(x=>`<div class="switchline"><span>${esc(x.intent||'unknown')}</span><strong>${x.count}</strong></div>`).join('')||'<div class="empty">No processed-message events yet.</div>'}</div><div class="card"><h3>Outcome distribution</h3>${(a.outcomes||[]).map(x=>`<div class="switchline"><span>${esc(x.status||'unknown')}</span><strong>${x.count}</strong></div>`).join('')||'<div class="empty">No outcomes yet.</div>'}<div class="sub" style="margin-top:12px">Review customer messages below to measure intent accuracy. Catalogue correctness and groundedness can also be submitted through the review API.</div></div></div><div class="card" style="margin-top:14px"><h3>Review recent conversations</h3>${(state.aiEvaluations||[]).map(e=>`<div class="knowledge-row"><div class="sub">${date(e.created_at)} · ${esc(e.intent)} · confidence ${Math.round(Number(e.confidence||0)*100)}%</div><div style="margin-top:6px"><strong>Customer:</strong> ${esc(e.customer_text||'')}</div><div style="margin-top:5px"><strong>Meridin:</strong> ${esc(e.reply_text||'')}</div><div style="display:flex;gap:8px;align-items:center;margin-top:10px;flex-wrap:wrap"><span class="sub">Intent review: ${e.intent_correct===true?'Correct':e.intent_correct===false?'Incorrect':'Not reviewed'}</span><button class="btn" data-review-event="${esc(e.id)}" data-review-value="true">Intent correct</button><button class="btn" data-review-event="${esc(e.id)}" data-review-value="false">Intent incorrect</button></div></div>`).join('')||'<div class="empty">No recent evaluation events yet. Send test messages to start collecting quality data.</div>'}</div>`}

  function settings(){const b=state.business||{},a=state.automation||{};return `<div class="page-head"><div><div class="eyebrow">Workspace configuration</div><h1 class="page-title">Settings</h1><div class="sub">Control business context and how Meridin responds to customers.</div></div><button class="btn primary" data-save-settings>Save changes</button></div><div class="grid two"><div class="card"><h3>Business information</h3><div class="form-grid"><div class="field full"><label>Business information</label><textarea class="textarea" id="businessInfo" rows="4">${esc(b.business_information||'')}</textarea></div><div class="field"><label>Location</label><input class="input" id="location" value="${esc(b.location||'')}"></div><div class="field"><label>Business hours</label><input class="input" id="hours" value="${esc(b.business_hours||'')}"></div><div class="field full"><label>Delivery information</label><textarea class="textarea" id="delivery" rows="3">${esc(b.delivery_info||'')}</textarea></div><div class="field"><label>Contact</label><input class="input" id="contact" value="${esc(b.contact||'')}"></div><div class="field"><label>Language</label><select class="select" id="language"><option>English</option><option>Malayalam</option><option>Manglish</option><option>English + Malayalam</option></select></div></div></div><div class="card"><h3>Automation</h3><div class="switchline"><div><strong style="font-size:13px">DM automation</strong><div class="sub">Automatically process incoming Instagram DMs.</div></div><button class="toggle ${a.automation_enabled?'on':''}" id="autoToggle"><span></span></button></div><div class="switchline"><div><strong style="font-size:13px">LLM fallback</strong><div class="sub">Allow the configured LLM fallback for messages not handled deterministically.</div></div><button class="toggle ${a.llm_enabled?'on':''}" id="llmToggle"><span></span></button></div><div class="field" style="margin-top:16px"><label>Response tone</label><select class="select" id="tone"><option>Friendly</option><option>Professional</option><option>Minimal</option><option>Warm</option><option>Casual</option></select></div><div class="field" style="margin-top:12px"><label>Low confidence threshold</label><input class="input" id="threshold" type="number" min="0" max="1" step="0.01" value="${a.low_confidence_threshold??.55}"></div></div></div>`}

  function optionChoices(type, selected=''){
    const list=state.catalogueOptions?.[type]||[];const values=list.map(x=>x.value);if(selected&&!values.includes(selected))values.unshift(selected);
    return `<option value="">Select ${esc(type.replaceAll('_',' '))}</option>`+values.map(v=>`<option value="${esc(v)}" ${selected===v?'selected':''}>${esc(v)}</option>`).join('');
  }
  function multiOptionField(type,name,selected=[]){
    const list=state.catalogueOptions?.[type]||[];const current=Array.isArray(selected)?selected:[];const values=[...list.map(x=>x.value)];current.forEach(v=>{if(v&&!values.includes(v))values.unshift(v)});
    if(!values.length)return `<div class="field"><label>${esc(type==='color'?'Colours':'Sizes')} (comma-separated)</label><input class="input" name="${name}_text" value="${esc(current.join(', '))}" placeholder="${type==='color'?'Black, Blue':'S, M, L, XL'}"></div>`;
    return `<div class="field"><label>${esc(type==='color'?'Colours':'Sizes')} (select multiple)</label><select class="select" name="${name}" multiple size="4">${values.map(v=>`<option value="${esc(v)}" ${current.includes(v)?'selected':''}>${esc(v)}</option>`).join('')}</select><small class="sub">Use Ctrl (Windows) to select multiple values.</small></div>`;
  }
  let apparelTaxonomy = window.MERIDIN_CLOTHING_TAXONOMY || {};
  let variantPresets = window.MERIDIN_VARIANT_PRESETS || {};
  function categoryChildren(node){
    if(Array.isArray(node)) return node;
    if(node && typeof node==='object') return Object.keys(node);
    return [];
  }
  function categoryNodeAtPath(path){
    let node=apparelTaxonomy;
    for(const part of path){ if(Array.isArray(node)){ node=node.includes(part)?[]:[]; } else { node=node?.[part] ?? []; } }
    return node;
  }
  function renderCategoryMenu(node, prefix=[], selectedPath=[], expandedPaths=new Set()){
    const entries=categoryChildren(node);
    return `<ul class="category-menu-list">${entries.map(name=>{const next=Array.isArray(node)?[]:(node?.[name]??[]);const children=categoryChildren(next);const full=[...prefix,name];const key=JSON.stringify(full);const selected=full.length<=selectedPath.length&&full.every((v,i)=>selectedPath[i]===v);const expanded=expandedPaths.has(key);return `<li class="category-menu-item ${children.length?'has-children':''} ${selected?'is-selected':''} ${expanded?'is-expanded':''}"><div class="category-menu-row"><button type="button" class="category-menu-label" data-category-pick="${esc(key)}">${esc(name)}</button>${children.length?`<button type="button" class="category-menu-arrow" data-category-expand="${esc(key)}" aria-label="Show ${esc(name)} subcategories" aria-expanded="${expanded}">${expanded?'⌄':'›'}</button>`:''}</div>${children.length&&expanded?`<div class="category-submenu">${renderCategoryMenu(next,full,selectedPath,expandedPaths)}</div>`:''}</li>`}).join('')}</ul>`;
  }
  function autoSku(title,suffix='AUTO'){const base=String(title||'PRODUCT').normalize('NFKD').replace(/[^a-zA-Z0-9]+/g,'-').replace(/^-|-$/g,'').toUpperCase().slice(0,18)||'PRODUCT';return `MER-${base}-${suffix}`}
  function parseVariantLines(v){return String(v||'').split(',').map(x=>x.trim()).filter(Boolean)}
  function normalizeVariantOptions(options){return (options||[]).filter(o=>o&&o.name&&Array.isArray(o.values)&&o.values.length).map(o=>({name:String(o.name).trim(),values:[...new Set(o.values.map(v=>String(v).trim()).filter(Boolean))]})).filter(o=>o.name&&o.values.length).slice(0,3)}
  function buildVariantCombos(options){
    let combos=[{}];
    for(const option of normalizeVariantOptions(options)){
      const next=[];
      for(const combo of combos) for(const value of option.values){next.push({...combo,[option.name]:value});if(next.length>=100)break}
      combos=next.slice(0,100);
    }
    return combos;
  }
  function renderVariantOptionEditor(options, existingVariants=[]){
    const opts=(options||[]).filter(o=>o&&o.name).slice(0,3).map(o=>({name:String(o.name).trim()||'Custom',values:[...new Set((Array.isArray(o.values)?o.values:[]).map(v=>String(v).trim()).filter(Boolean))]}));const combos=buildVariantCombos(opts.filter(o=>o.values.length));
    const variantRows=combos.map((combo,i)=>{const existing=(existingVariants||[]).find(v=>opts.every(o=>String(v.options?.[o.name]??'')===String(combo[o.name]??'')))||{};return `<tr><td><strong>${esc(opts.map(o=>combo[o.name]).filter(Boolean).join(' / ')||`Variant ${i+1}`)}</strong></td><td><input class="input variant-sku" data-variant-index="${i}" value="${esc(existing.sku||'')}" placeholder="Auto SKU"></td><td><input class="input variant-price" data-variant-index="${i}" type="number" min="0" step="0.01" value="${existing.price??''}" placeholder="Product price"></td><td><input class="input variant-qty" data-variant-index="${i}" type="number" min="0" value="${existing.quantity??0}"></td></tr>`}).join('');
    const optionNames=Object.keys(variantPresets).filter(n=>n.toLowerCase()!=='target gender'&&!opts.some(o=>o.name.toLowerCase()===n.toLowerCase()));
    const optionCards=opts.map((o,i)=>{const values=variantPresets[o.name]||[];const selected=new Set(o.values);return `<div class="variant-option-card" data-option-index="${i}"><div class="variant-option-card-head"><label for="variantOptionSelect${i}">Option ${i+1}</label><button type="button" class="btn variant-remove" data-remove-option="${i}">Remove</button></div><select class="select variant-option-name" id="variantOptionSelect${i}" data-option-index="${i}">${Object.keys(variantPresets).filter(n=>n.toLowerCase()!=='target gender').map(n=>`<option value="${esc(n)}" ${n.toLowerCase()===o.name.toLowerCase()?'selected':''}>${esc(n)}</option>`).join('')}</select><div class="variant-values-heading">Select values</div><div class="variant-values-checklist">${values.map(v=>`<label class="variant-value-check"><input type="checkbox" data-option-value-index="${i}" value="${esc(v)}" ${selected.has(v)?'checked':''}><span>${esc(v)}</span></label>`).join('')}</div><div class="variant-selected-summary">${o.values.length?`${o.values.length} value${o.values.length===1?'':'s'} selected`:'Select one or more values above.'}</div></div>`}).join('');
    return `<div class="variant-builder"><div class="variant-options-list">${optionCards}</div><div class="variant-add-row">${opts.length<3?`<div class="variant-add-control"><label for="newVariantOption">Add another option</label><select class="select" id="newVariantOption"><option value="">Choose option…</option>${optionNames.map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('')}</select></div><button type="button" class="btn" data-add-variant-option ${opts.length>=3?'disabled':''}>＋ Add option</button>`:'<div class="sub">You can add up to 3 options.</div>'}</div><div class="sub" style="margin-top:8px">${combos.length?`${combos.length} variant combination${combos.length===1?'':'s'} generated (up to 100 shown).`:'Add an option and select its values to create variants.'}</div>${combos.length?`<div class="variant-table-wrap"><table class="table variant-table"><thead><tr><th>Variant</th><th>SKU</th><th>Price (₹)</th><th>Quantity</th></tr></thead><tbody>${variantRows}</tbody></table></div>`:''}</div>`;
  }
  async function openProductModal(product=null){
    try{const cfg=await api('/api/catalogue-config');apparelTaxonomy=cfg.taxonomy||apparelTaxonomy;variantPresets=cfg.variant_presets||variantPresets;state.catalogueOptions=await api('/api/catalogue-options')}catch{}
    const p=product||{};const m=document.createElement('div');m.className='modal-backdrop';
    const existingPath=Array.isArray(p.category_path)?p.category_path:[p.department,p.category,p.subcategory,p.product_type].filter(Boolean);
    const initialOptions=normalizeVariantOptions(p.variant_options?.length?p.variant_options:[...(p.sizes?.length?[{name:'Size',values:p.sizes}]:[]),...(p.colors?.length?[{name:'Color',values:p.colors}]:[])]);
    const path=[...existingPath];
    m.innerHTML=`<div class="modal product-editor-modal"><div class="modal-head"><div><div class="eyebrow">PRODUCT CATALOGUE</div><h2>${product?'Edit product':'Add product'}</h2></div><button class="icon-btn" data-close aria-label="Close">×</button></div><form id="productForm">
      <div class="shopify-product-layout"><div class="shopify-product-main">
        <section class="shopify-card"><div class="field"><label>Title</label><input class="input product-title-input" name="name" required maxlength="200" value="${esc(p.name||'')}" placeholder="e.g. Floral Cotton Kurti"></div><div class="field" style="margin-top:16px"><label>Description</label><textarea class="textarea" name="description" rows="6" placeholder="Describe the product, fit, fabric and key details…">${esc(p.description||'')}</textarea></div><div class="field target-gender-main" style="margin-top:16px"><label>Target gender</label><select class="select" name="target_gender"><option value="">Select gender</option>${(variantPresets['Target gender']||[]).map(v=>`<option value="${esc(v)}" ${p.target_gender===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div></section>
        <section class="shopify-card"><div class="shopify-section-head"><div><h3>Category</h3><p>Choose a category to help organize your products and make them easier to find.</p></div></div><div class="category-path-selectors" id="categoryPathSelectors"></div><div class="category-path-summary" id="categoryPathSummary"></div><div class="field" style="margin-top:14px"><label>Brand</label><input class="input" name="brand" value="${esc(p.brand||'')}" placeholder="Brand name"></div></section>
        <section class="shopify-card"><div class="shopify-section-head"><div><h3>Media</h3><p>Add photos of this product</p></div></div><label class="product-upload-drop" for="productImageFile"><span class="upload-icon">＋</span><strong>Add media</strong><span>JPEG, PNG or WebP · max 8 MB</span><input id="productImageFile" name="product_image_file" type="file" accept="image/jpeg,image/png,image/webp" hidden></label><div id="productImagePreviewWrap" class="product-image-preview-wrap" style="display:${p.image_url?'flex':'none'}"><img id="productImagePreview" src="${esc(p.image_url||'')}" alt="Product image preview"><div><strong id="productImagePreviewLabel">${p.image_url?'Current product image':'Selected image'}</strong><div class="sub">Product image</div></div></div><input type="hidden" name="existing_image_url" value="${esc(p.image_url||'')}"></section>
        <section class="shopify-card"><div class="shopify-section-head"><div><h3>Pricing</h3><p>Set the price customers will see</p></div></div><div class="form-grid"><div class="field"><label>Price (₹)</label><input class="input" name="price" type="number" min="0" step="0.01" required value="${p.price??''}" placeholder="0.00"></div><div class="field"><label>Compare-at / sale price (₹)</label><input class="input" name="sale_price" type="number" min="0" step="0.01" value="${p.sale_price??''}" placeholder="Optional"></div></div></section>
        <section class="shopify-card"><div class="shopify-section-head"><div><h3>Inventory</h3><p>Track stock for this product</p></div></div><div class="form-grid"><div class="field"><label>SKU <span class="sub">· generated automatically</span></label><input class="input" name="sku" value="${esc(p.sku||'')}" placeholder="Generated from product title" readonly></div><div class="field"><label>Available quantity</label><input class="input" name="quantity" type="number" min="0" value="${p.quantity??0}"></div></div></section>
        <section class="shopify-card"><div class="shopify-section-head"><div><h3>Variants</h3><p>Offer this product in different sizes, colors or other options.</p></div></div><div id="variantEditor"></div></section>

      </div><aside class="shopify-product-side"><section class="shopify-card"><div class="shopify-section-head"><h3>Status</h3></div><select class="select" name="status"><option value="active" ${(p.active!==false)?'selected':''}>Active</option><option value="draft" ${p.active===false?'selected':''}>Draft</option></select><p class="sub">Active products can be used by Meridin's Instagram automation.</p></section><section class="shopify-card"><div class="shopify-section-head"><h3>Organization</h3></div><div class="field"><label>Product type (optional)</label><input class="input" name="product_type_extra" value="${esc(p.product_type_extra||'')}" placeholder="e.g. Everyday wear"></div></section><section class="shopify-card"><div class="shopify-section-head"><h3>Search preview</h3></div><div class="sub">This product's title, description, category, options, price and stock can help Meridin answer customer DMs using your actual catalogue data.</div></section></aside></div>
      <div id="formError"></div><div class="product-editor-footer"><span class="sub">Changes are saved to this brand's catalogue.</span><div><button type="button" class="btn" data-close>Cancel</button> <button type="submit" class="btn primary">${product?'Save changes':'Save product'}</button></div></div></form></div>`;
    document.body.appendChild(m);m.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>m.remove());
    const imageInput=m.querySelector('#productImageFile'), previewWrap=m.querySelector('#productImagePreviewWrap'), preview=m.querySelector('#productImagePreview'), previewLabel=m.querySelector('#productImagePreviewLabel');
    imageInput.onchange=()=>{const file=imageInput.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){imageInput.value='';toast('Choose a JPEG, PNG or WebP image');return}if(file.size>8*1024*1024){imageInput.value='';toast('Image must be 8 MB or smaller');return}preview.src=URL.createObjectURL(file);previewLabel.textContent='Selected image (not uploaded yet)';previewWrap.style.display='flex'};
    let categoryPickerOpen=false;const expandedCategoryPaths=new Set();
    function renderCategoryPath(){
      const host=m.querySelector('#categoryPathSelectors');const selectedText=path.length?path[path.length-1]:'Choose department and category';
      host.innerHTML=`<div class="category-picker"><div class="category-picker-label">Department and category</div><button type="button" class="category-picker-trigger" id="categoryPickerTrigger" aria-expanded="${categoryPickerOpen}"><span>${esc(selectedText)}</span><span class="category-trigger-chevron">${categoryPickerOpen?'⌃':'⌄'}</span></button>${categoryPickerOpen?`<div class="category-picker-dropdown">${renderCategoryMenu(apparelTaxonomy,[],path,expandedCategoryPaths)}</div>`:''}</div>`;
      host.querySelector('#categoryPickerTrigger').onclick=()=>{categoryPickerOpen=!categoryPickerOpen;renderCategoryPath()};
      host.querySelectorAll('[data-category-expand]').forEach(btn=>btn.onclick=()=>{const key=btn.dataset.categoryExpand;if(expandedCategoryPaths.has(key))expandedCategoryPaths.delete(key);else expandedCategoryPaths.add(key);renderCategoryPath()});
      host.querySelectorAll('[data-category-pick]').forEach(btn=>btn.onclick=()=>{try{const picked=JSON.parse(btn.dataset.categoryPick);const node=categoryNodeAtPath(picked);if(categoryChildren(node).length){const key=JSON.stringify(picked);if(expandedCategoryPaths.has(key))expandedCategoryPaths.delete(key);else expandedCategoryPaths.add(key);renderCategoryPath();return}path.splice(0,path.length,...picked);categoryPickerOpen=false;expandedCategoryPaths.clear();renderCategoryPath()}catch{}});
      const summary=m.querySelector('#categoryPathSummary');summary.textContent=path.length?`${path[path.length-1]} in ${path[0]}`:'No category selected';
    }
    renderCategoryPath();
    let workingOptions=initialOptions;
    function renderVariantEditor(){
      const oldHost=m.querySelector('#variantEditor');const oldScroll=oldHost?.querySelector('.variant-values-checklist')?.scrollTop||0;
      oldHost.innerHTML=renderVariantOptionEditor(workingOptions,p.variants||[]);const host=oldHost;
      const checklist=host.querySelector('.variant-values-checklist');if(checklist)checklist.scrollTop=oldScroll;
      host.querySelectorAll('.variant-option-name').forEach(sel=>sel.onchange=()=>{const i=Number(sel.dataset.optionIndex);const name=sel.value;workingOptions[i]={name,values:[]};renderVariantEditor()});
      host.querySelectorAll('[data-option-value-index]').forEach(box=>box.onchange=()=>{const i=Number(box.dataset.optionValueIndex);const name=workingOptions[i].name;const selected=[...host.querySelectorAll(`[data-option-value-index="${i}"]:checked`)].map(x=>x.value);workingOptions[i].values=selected;renderVariantEditor()});
      host.querySelectorAll('[data-remove-option]').forEach(btn=>btn.onclick=()=>{workingOptions.splice(Number(btn.dataset.removeOption),1);renderVariantEditor()});
      const add=host.querySelector('[data-add-variant-option]');if(add)add.onclick=()=>{const sel=host.querySelector('#newVariantOption');if(!sel?.value)return;const name=sel.value;workingOptions.push({name,values:[]});renderVariantEditor()};
    }
    renderVariantEditor();
    const skuInput=m.querySelector('[name="sku"]');const skuSuffix=Math.random().toString(36).slice(2,6).toUpperCase();if(!p.sku)skuInput.value=autoSku(m.querySelector('[name="name"]').value,skuSuffix);m.querySelector('[name="name"]').addEventListener('input',()=>{if(!product)skuInput.value=autoSku(m.querySelector('[name="name"]').value,skuSuffix)});
    m.querySelector('form').onsubmit=async e=>{e.preventDefault();const form=e.target;const submit=form.querySelector('button[type="submit"]');submit.disabled=true;submit.textContent='Saving…';const f=new FormData(form);
      try{
        let imageUrl=p.image_url||'';const imageFile=imageInput.files?.[0];
        if(imageFile){submit.textContent='Uploading image…';const fd=new FormData();fd.append('file',imageFile);const response=await fetch('/api/products/upload-image',{method:'POST',headers:token()?{Authorization:`Bearer ${token()}`}:{},body:fd});let uploaded={};try{uploaded=await response.json()}catch{}if(!response.ok)throw new Error(uploaded.detail||`Image upload failed (${response.status})`);imageUrl=uploaded.url;}
        const opts=normalizeVariantOptions(workingOptions);const combos=buildVariantCombos(opts);const variants=combos.map((combo,i)=>({options:combo,sku:m.querySelector(`.variant-sku[data-variant-index="${i}"]`)?.value.trim()||`${f.get('sku')||'MER-PRODUCT'}-${String(i+1).padStart(3,'0')}`,price:m.querySelector(`.variant-price[data-variant-index="${i}"]`)?.value?Number(m.querySelector(`.variant-price[data-variant-index="${i}"]`).value):null,quantity:Number(m.querySelector(`.variant-qty[data-variant-index="${i}"]`)?.value||0)}));
                const pathValues=path.slice();const body={name:f.get('name'),sku:f.get('sku')||autoSku(f.get('name'),skuSuffix),price:Number(f.get('price')),sale_price:f.get('sale_price')?Number(f.get('sale_price')):null,department:pathValues[0]||p.department||'',category:pathValues[1]||p.category||'',subcategory:pathValues[2]||p.subcategory||'',product_type:pathValues.length>3?pathValues.slice(3).join(' / '):(pathValues[2]||p.product_type||''),category_path:pathValues.length?pathValues:(p.category_path||[]),target_gender:f.get('target_gender')||'',brand:f.get('brand')||'',description:f.get('description')||'',sizes:[...new Set(opts.filter(o=>o.name.toLowerCase()==='size').flatMap(o=>o.values))],colors:[...new Set(opts.filter(o=>o.name.toLowerCase()==='color').flatMap(o=>o.values))],variant_options:opts,variants,quantity:Number(f.get('quantity')||0),stock:Number(f.get('quantity')||0)>0,image_url:imageUrl,active:f.get('status')==='active',product_type_extra:f.get('product_type_extra')||''};
        submit.textContent='Saving product…';const d=product?await api('/api/products/'+product.id,{method:'PATCH',body:JSON.stringify(body)}):await api('/api/products',{method:'POST',body:JSON.stringify(body)});if(product)state.products=state.products.map(x=>x.id===product.id?d:x);else state.products.unshift(d);m.remove();render();toast(product?'Product updated':'Product added');
      }catch(err){const x=document.createElement('div');x.className='error';x.textContent=err.message;m.querySelector('#formError').replaceChildren(x);submit.disabled=false;submit.textContent=product?'Save changes':'Save product'}
    };
  }

  async function loadMessages(id){const box=$('#messages');if(!box)return;try{const ms=await api('/api/conversations/'+id+'/messages');box.innerHTML=ms.map(m=>`<div class="bubble ${m.direction==='inbound'?'in':m.sender_id==='human'?'human':'out'}">${esc(m.text)}<small>${m.direction==='inbound'?'Customer':m.sender_id==='human'?'You':'Meridin'} · ${date(m.created_at)}</small></div>`).join('')||'<div class="empty">No messages yet.</div>';box.scrollTop=box.scrollHeight}catch(e){box.innerHTML=`<div class="error">${esc(e.message)}</div>`}}

  function bind(){document.querySelectorAll('[data-go]').forEach(x=>x.onclick=()=>{state.tab=x.dataset.go;render()});document.querySelectorAll('[data-open-convo]').forEach(x=>x.onclick=()=>{state.selected=x.dataset.openConvo;state.tab='conversations';render()});const qs=$('#productSearch');if(qs)qs.oninput=e=>{window.catalogueQuery=e.target.value;render()};document.querySelectorAll('[data-add-product]').forEach(x=>x.onclick=()=>openProductModal());document.querySelectorAll('[data-visual-reindex]').forEach(x=>x.onclick=async()=>{x.disabled=true;x.textContent='Indexing…';try{const r=await api('/api/products/visual-reindex',{method:'POST'});toast(`Image search index: ${r.indexed} indexed, ${r.failed} failed`)}catch(e){toast(e.message)}finally{x.disabled=false;x.textContent='Reindex image search'}});document.querySelectorAll('[data-edit]').forEach(x=>x.onclick=()=>openProductModal(state.products.find(p=>p.id===x.dataset.edit)));document.querySelectorAll('[data-refresh]').forEach(x=>x.onclick=async()=>{await refresh();render();toast('Data refreshed')});const toggle=$('[data-toggle-auto]');if(toggle)toggle.onclick=async()=>{try{await api('/api/clients/automation-settings',{method:'PATCH',body:JSON.stringify({...state.automation,automation_enabled:!state.automation.automation_enabled})});state.automation.automation_enabled=!state.automation.automation_enabled;render();toast('Automation updated')}catch(e){toast(e.message)}};document.querySelectorAll('[data-select-convo]').forEach(x=>x.onclick=()=>{state.selected=x.dataset.selectConvo;render();loadMessages(state.selected)});document.querySelectorAll('[data-take]').forEach(x=>x.onclick=async()=>{await api('/api/conversations/'+x.dataset.take+'/takeover',{method:'POST'});await refresh();render();loadMessages(x.dataset.take);toast('Conversation handed to you')});document.querySelectorAll('[data-resume]').forEach(x=>x.onclick=async()=>{await api('/api/conversations/'+x.dataset.resume+'/resume',{method:'POST'});await refresh();render();loadMessages(x.dataset.resume);toast('Automation resumed')});const rf=$('#replyForm');if(rf)rf.onsubmit=async e=>{e.preventDefault();try{await api('/api/conversations/'+state.selected+'/reply',{method:'POST',body:JSON.stringify({text:$('#replyText').value})});$('#replyText').value='';await loadMessages(state.selected);toast('Reply sent')}catch(err){toast(err.message)}};if($('#messages')&&state.selected)loadMessages(state.selected);const mf=$('#clientMetaForm');if(mf)mf.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(mf));try{const saved=await api('/api/clients/meta-config',{method:'PUT',body:JSON.stringify(d)});state.metaConfig=saved;toast('Meta app settings saved securely. Configure the same webhook verify token in Meta.');await refresh();render()}catch(err){toast(err.message)}};const imf=$('#manualInstagramForm');if(imf)imf.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(imf));if(!String(d.access_token||'').trim())delete d.access_token;try{await api('/api/instagram/accounts',{method:'POST',body:JSON.stringify(d)});await refresh();render();toast('Instagram credentials saved securely. Enable messaging after checking the webhook setup.')}catch(err){toast(err.message)}};document.querySelectorAll('[data-copy-meta-url]').forEach(b=>b.onclick=async()=>{const el=$('#metaWebhookUrl');try{await navigator.clipboard.writeText(el.value);toast('Webhook URL copied')}catch(e){el.select();toast('Select and copy the URL manually')}});document.querySelectorAll('[data-subscribe]').forEach(x=>x.onclick=async()=>{try{await api('/api/instagram/accounts/'+x.dataset.subscribe+'/subscribe',{method:'POST'});await refresh();render();toast('Instagram messaging enabled')}catch(e){toast(e.message)}});const map=$('[data-map]');if(map)map.onclick=async()=>{try{await api('/api/instagram/mappings',{method:'POST',body:JSON.stringify({instagram_media_id:$('#mapMedia').value,instagram_post_id:$('#mapPost').value,product_id:$('#mapProduct').value})});toast('Product mapping saved')}catch(e){toast(e.message)}};const at=$('#autoToggle'),lt=$('#llmToggle');if(at)at.onclick=()=>at.classList.toggle('on');if(lt)lt.onclick=()=>lt.classList.toggle('on');const kf=$('#knowledgeForm');if(kf)kf.onsubmit=async e=>{e.preventDefault();const fd=new FormData(kf);try{await api('/api/knowledge',{method:'POST',body:JSON.stringify({title:fd.get('title'),category:fd.get('category'),content:fd.get('content'),tags:String(fd.get('tags_text')||'').split(',').map(x=>x.trim()).filter(Boolean)})});await loadKnowledge();render();toast('Knowledge document saved')}catch(err){toast(err.message)}};document.querySelectorAll('[data-delete-knowledge]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this knowledge document?'))return;try{await api('/api/knowledge/'+b.dataset.deleteKnowledge,{method:'DELETE'});await loadKnowledge();render();toast('Document deleted')}catch(err){toast(err.message)}});const rk=$('[data-refresh-knowledge]');if(rk)rk.onclick=async()=>{await loadKnowledge();render()};const ra=$('[data-refresh-ai]');if(ra)ra.onclick=async()=>{await loadAiAnalytics();render()};document.querySelectorAll('[data-review-event]').forEach(b=>b.onclick=async()=>{try{await api('/api/ai/evaluations/'+b.dataset.reviewEvent+'/review',{method:'POST',body:JSON.stringify({intent_correct:b.dataset.reviewValue==='true'})});await loadAiAnalytics();render();toast('Evaluation review saved')}catch(err){toast(err.message)}});const save=$('[data-save-settings]');if(save)save.onclick=async()=>{try{await api('/api/clients/business-settings',{method:'PATCH',body:JSON.stringify({business_information:$('#businessInfo').value,location:$('#location').value,delivery_info:$('#delivery').value,business_hours:$('#hours').value,contact:$('#contact').value,language:$('#language').value,tone:$('#tone').value})});await api('/api/clients/automation-settings',{method:'PATCH',body:JSON.stringify({automation_enabled:$('#autoToggle').classList.contains('on'),llm_enabled:$('#llmToggle').classList.contains('on'),language:$('#language').value,tone:$('#tone').value,human_handoff_on_unknown:true,low_confidence_threshold:Number($('#threshold').value)})});await refresh();render();toast('Settings saved')}catch(e){toast(e.message)}}}
  async function refresh(){const [b,a,p,c,ac,mc,co]=await Promise.all([api('/api/clients/business-settings'),api('/api/clients/automation-settings'),api('/api/products'),api('/api/conversations'),api('/api/instagram/accounts'),api('/api/clients/meta-config'),api('/api/catalogue-options')]);state.business=b;state.automation=a;state.products=p;state.conversations=c;state.accounts=ac;state.metaConfig=mc;state.catalogueOptions=co;if(!state.selected&&c[0])state.selected=c[0].id;}
  boot();
})();
